// grounded-copy for dsh: the session policy, the skill, and the /grounded command.
//
// Generated by scripts/build_dsh_adapter.py in the grounded-copy repository.
// grounded.json holds the policy texts the builder assembles from SKILL.md.

import { lstatSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { readFile } from 'node:fs/promises'
import { homedir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const DATA = JSON.parse(readFileSync(join(HERE, 'grounded.json'), 'utf8'))
const SKILL_DIR = join(HERE, 'skills', 'grounded-copy')
const SKILL_FILE = join(SKILL_DIR, 'SKILL.md')

const VALID = new Set(['chat', 'copy', 'off'])
const DEFAULT = 'chat'
// The words hooks/_preference.py accepts for --set, and the stored legacy name.
const ARGUMENTS = new Map([
  ['chat', 'chat'], ['technical', 'chat'], ['copy', 'copy'], ['marketing', 'copy'], ['off', 'off'],
])
const LEGACY = new Map([['technical', 'chat']])
const MAX_PREFERENCE_BYTES = 64
// BUNDLED_SKILL_RANK in @deepseek-ai/dsh-skill: a copy the user installed outranks this one.
const SKILL_RANK = 600
// dsh orders its own sections from -1000 to 10200. This one follows the
// first-party guidance and precedes the harness-source section at 10000.
const SECTION_ORDER = 9900

const SKILL = {
  path: SKILL_FILE,
  name: DATA.skill.name,
  description: DATA.skill.description,
  invocation: { modelInvocable: true, userInvocable: true },
  provider: 'grounded-copy',
  source: 'bundled',
  resourceBase: { kind: 'directory', path: SKILL_DIR },
}

function preferencePath() {
  return join(process.env.DSH_HOME || join(homedir(), '.dsh'), 'grounded-copy', 'profile')
}

// [profile, source]: a name from VALID, and why. Reads only.
function resolvePreference(path) {
  let value
  try {
    const stat = lstatSync(path)
    if (stat.isSymbolicLink() || stat.size > MAX_PREFERENCE_BYTES) return [DEFAULT, 'unreadable']
    value = readFileSync(path, 'utf8').trim().toLowerCase()
  } catch (error) {
    return [DEFAULT, error.code === 'ENOENT' ? 'absent' : 'unreadable']
  }
  value = LEGACY.get(value) || value
  return VALID.has(value) ? [value, 'recorded'] : [DEFAULT, 'unreadable']
}

function statusLine(path) {
  const [profile, source] = resolvePreference(path)
  if (source === 'recorded') {
    const restore = profile === 'off' ? '; run /grounded chat to restore' : ''
    return `grounded profile: ${profile} (recorded at ${path})${restore}`
  }
  const reason = source === 'absent' ? 'no preference' : 'unreadable preference'
  return `grounded profile: ${profile} (default, ${reason} at ${path})`
}

// Save through a renamed temporary file, so a reader never sees part of one.
// Returns an error text, or '' once the file reads back as written.
function writePreference(profile, path) {
  try {
    if (lstatSync(path).isSymbolicLink()) {
      return `grounded: ${path} is a symlink, which the plugin reads as unreadable. Remove it and run /grounded again.`
    }
  } catch {
    // No file yet: the first save creates it.
  }
  const temporary = join(dirname(path), `.profile-${process.pid}`)
  try {
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(temporary, profile + '\n', 'utf8')
    renameSync(temporary, path)
  } catch (error) {
    rmSync(temporary, { force: true })
    return `grounded: write failed at ${path}: ${error.message}`
  }
  const [stored, source] = resolvePreference(path)
  return stored === profile ? '' : `grounded: wrote ${profile} at ${path}, read back ${stored} (${source})`
}

function runCommand(rawInput) {
  const path = preferencePath()
  const word = String(rawInput ?? '').trim().toLowerCase()
  if (!word) return { kind: 'success', text: statusLine(path) }
  const profile = ARGUMENTS.get(word)
  if (!profile) {
    return { kind: 'error', text: `grounded: unknown profile ${JSON.stringify(word)}; choose chat, copy, or off` }
  }
  const failure = writePreference(profile, path)
  return failure ? { kind: 'error', text: failure } : { kind: 'success', text: statusLine(path) }
}

// The policy for the saved mode, or '' for off, which dsh leaves out of the prompt.
function sessionPolicy() {
  const [profile] = resolvePreference(preferencePath())
  return profile === 'off' ? '' : DATA.policy[profile]
}

const skillProvider = {
  name: SKILL.provider,
  list: () => Promise.resolve([{ ...SKILL, rank: SKILL_RANK, locator: SKILL_FILE }]),
  async get() {
    const text = await readFile(SKILL_FILE, 'utf8')
    return { ...SKILL, content: text.replace(/^---[\s\S]*?---\s*/, '') }
  },
}

export const name = 'grounded-copy'
export const inject = ['systemPrompt']

export function apply(ctx) {
  // dsh assembles the prompt before every model step, so a saved mode reaches the next reply.
  ctx.systemPrompt.section({
    name: 'grounded-copy:policy', order: SECTION_ORDER, interpolate: false, text: sessionPolicy,
  })
  // A profile without these services still gets the policy.
  ctx.inject(['skills'], (scoped) => {
    scoped.skills.registerProvider(() => skillProvider)
  })
  ctx.inject(['commands'], (scoped) => {
    scoped.commands.register({
      name: 'grounded',
      description: 'Show or change the grounded-copy writing mode',
      handler: ({ rawInput }) => runCommand(rawInput),
    })
  })
}
